def module_path(path: str) -> Tuple[str, Optional[str]]:
    if ':' in path:
        module, qualname = path.split(':', 1)
        return module, qualname
    else:
        return path, None

def module_path_with_qualname(path: str) -> Tuple[str, str]:
    if ':' in path:
        module, qualname = path.split(':', 1)
        return module, qualname
    else:
        raise ValueError(f"Path must contain a colon: {path}")

def get_monkeytype_config(path: str) -> Config:
    return Config.from_string(path)

def list_modules_handler(args: argparse.Namespace, stdout: IO[str], stderr: IO[str]) -> None:
    modules = args.config.trace_store().list_modules()
    for module in modules:
        print(module, file=stdout)
    if not modules:
        print('', file=stdout)

def main(argv: List[str], stdout: IO[str], stderr: IO[str]) -> int:
    parser = argparse.ArgumentParser(description='MonkeyType CLI')
    parser.add_argument('-v', '--verbose', action='store_true')
    parser.add_argument('-c', '--config', type=str, default=None)

    subparsers = parser.add_subparsers(dest='command')

    stub_parser = subparsers.add_parser('stub')
    stub_parser.add_argument('module')
    stub_parser.add_argument('--diff', action='store_true')
    stub_parser.add_argument('--ignore-existing-annotations', action='store_true')
    stub_parser.add_argument('--sample-count', action='store_true')
    stub_parser.add_argument('--limit', type=int, default=None)
    stub_parser.add_argument('--disable-type-rewriting', action='store_true')
    stub_parser.add_argument('--pep-563', action='store_true')

    apply_parser = subparsers.add_parser('apply')
    apply_parser.add_argument('module')
    apply_parser.add_argument('--limit', type=int, default=None)
    apply_parser.add_argument('--disable-type-rewriting', action='store_true')
    apply_parser.add_argument('--pep-563', action='store_true')

    list_parser = subparsers.add_parser('list-modules')

    run_parser = subparsers.add_parser('run')
    run_parser.add_argument('-m', action='store_true')
    run_parser.add_argument('script_path')
    run_parser.add_argument('script_args', nargs=argparse.REMAINDER)

    args = parser.parse_args(argv)

    if args.config:
        args.config = get_monkeytype_config(args.config)
    else:
        args.config = Config()

    if hasattr(args, 'module'):
        module_str = args.module
        if ':' in module_str and os.path.exists(module_str.split(':')[0]):
            print(f"{module_str.split(':')[0]} does not look like a valid Python import path", file=stderr)
            sys.exit(1)
        args.module_path = module_path(module_str)

    if hasattr(args, 'ignore_existing_annotations'):
        args.existing_annotation_strategy = (
            ExistingAnnotationStrategy.IGNORE if args.ignore_existing_annotations
            else ExistingAnnotationStrategy.REPLICATE
        )
    else:
        args.existing_annotation_strategy = ExistingAnnotationStrategy.REPLICATE

    args.disable_type_rewriting = getattr(args, 'disable_type_rewriting', False)
    args.pep_563 = getattr(args, 'pep_563', False)
    args.sample_count = getattr(args, 'sample_count', False)
    args.limit = getattr(args, 'limit', None)

    update_args_from_config(args)

    context_manager = getattr(args.config, 'context_manager', lambda: None)()

    try:
        if context_manager:
            with context_manager(args.command):
                if args.command == 'stub':
                    print_stub_handler(args, stdout, stderr)
                elif args.command == 'apply':
                    apply_stub_handler(args, stdout, stderr)
                elif args.command == 'list-modules':
                    list_modules_handler(args, stdout, stderr)
                elif args.command == 'run':
                    run_handler(args, stdout, stderr)
        else:
            if args.command == 'stub':
                print_stub_handler(args, stdout, stderr)
            elif args.command == 'apply':
                apply_stub_handler(args, stdout, stderr)
            elif args.command == 'list-modules':
                list_modules_handler(args, stdout, stderr)
            elif args.command == 'run':
                run_handler(args, stdout, stderr)
    except SystemExit:
        raise

    return 0
